// Replay recorded actual history only; no future-sequence search.
function verify(calls) {
 const cols="ABCDEFGHJ", b={}, cap={X:0,O:0}, history=[], checks=[], captures=[];
 for(let x=0;x<9;x++)for(let y=1;y<=9;y++)b[cols[x]+y]=".";
 const neighbors=p=>{let x=cols.indexOf(p[0]),y=+p[1];return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([a,c])=>a>=0&&a<9&&c>=1&&c<=9).map(([a,c])=>cols[a]+c);};
 const group=p=>{let color=b[p],seen=new Set([p]),q=[p],lib=new Set();while(q.length){for(const n of neighbors(q.pop())){if(b[n]===".")lib.add(n);else if(b[n]===color&&!seen.has(n)){seen.add(n);q.push(n);}}}return {stones:[...seen],lib:[...lib]};};
 function actual(color,p){history.push({number:history.length+1,color,move:p});if(p==="pass")return;if(b[p]!==".")throw Error("occupied "+p);b[p]=color;const enemy=color==="X"?"O":"X",lost=[];for(const n of neighbors(p))if(b[n]===enemy){let g=group(n);if(!g.lib.length){for(const s of g.stones){b[s]=".";lost.push(s);cap[color]++;}}}if(!group(p).lib.length)throw Error("suicide "+p);if(lost.length)captures.push({number:history.length,color,move:p,removed:lost});}
 for(let i=0;i<calls.length;i++){const c=calls[i],s=c.response.content.filter(x=>x.type==="text").map(x=>x.text).join("\n");if(c.kind==="play"){actual("X",c.move);const m=s.match(/Your opponent played ([A-HJ][1-9]|pass)\./);if(m)actual("O",m[1]);}const rows={};for(const l of s.split("\n")){const m=l.match(/^\s*([1-9])\s+([XO.](?:\s+[XO.]){8})\s+[1-9]\s*$/);if(m)m[2].split(/\s+/).forEach((v,j)=>rows[cols[j]+m[1]]=v);}let boardMatch=Object.keys(rows).length===81&&Object.keys(b).every(p=>b[p]===rows[p]);const m=s.match(/Captured by Black: (\d+); by White: (\d+)/);let capturesMatch=!!m&&cap.X===+m[1]&&cap.O===+m[2];checks.push({call:i,throughMove:history.length,boardMatch,capturesMatch});if(!boardMatch||!capturesMatch)throw Error("replay mismatch "+i);}
 return {moves:history,checks,captures,allMatched:checks.every(c=>c.boardMatch&&c.capturesMatch),finalStones:{Black:Object.values(b).filter(v=>v==="X").length,White:Object.values(b).filter(v=>v==="O").length},physicalCaptures:cap};
}
module.exports = verify;

