// Replay recorded actual history only; no future-sequence search.
function verify(calls) {
 const cols="ABCDEFGHJ", b={}, cap={X:0,O:0}, history=[], checks=[], captures=[]; let ko=null, previousBefore=null;
 for(let x=0;x<9;x++)for(let y=1;y<=9;y++)b[cols[x]+y]=".";
 const neighbors=p=>{let x=cols.indexOf(p[0]),y=+p[1];return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([a,c])=>a>=0&&a<9&&c>=1&&c<=9).map(([a,c])=>cols[a]+c);};
 const group=p=>{let color=b[p],seen=new Set([p]),q=[p],lib=new Set();while(q.length){for(const n of neighbors(q.pop())){if(b[n]===".")lib.add(n);else if(b[n]===color&&!seen.has(n)){seen.add(n);q.push(n);}}}return {stones:[...seen],lib:[...lib]};};
 function actual(color,p){history.push({number:history.length+1,color,move:p});if(p==="pass"){ko=null;previousBefore=JSON.stringify(b);return;} const before=JSON.stringify(b);if(b[p]!==".")throw Error("occupied "+p);b[p]=color;const enemy=color==="X"?"O":"X",lost=[];for(const n of neighbors(p))if(b[n]===enemy){let g=group(n);if(!g.lib.length){for(const s of g.stones){b[s]=".";lost.push(s);cap[color]++;}}}if(!group(p).lib.length)throw Error("suicide "+p);if(previousBefore===JSON.stringify(b))throw Error("immediate ko "+p); previousBefore=before; const current=group(p); ko=lost.length===1&&current.stones.length===1&&current.lib.length===1?lost[0]:null; if(lost.length)captures.push({number:history.length,color,move:p,removed:lost});}
 for(let i=0;i<calls.length;i++){const c=calls[i],s=c.response.content.filter(x=>x.type==="text").map(x=>x.text).join("\n");if(c.action==="choose_opponent"){const m=s.match(/It plays first: ([A-HJ][1-9])\./);if(!m)throw Error("opening not parsed");actual("X",m[1]);} if(c.action==="play"){actual("O",c.move);const m=s.match(/Your opponent played ([A-HJ][1-9]|pass)\./);if(m)actual("X",m[1]);else if(/Your opponent passed\./.test(s))actual("X","pass");}const rows={};for(const l of s.split("\n")){const m=l.match(/^\s*([1-9])\s+([XO.](?:\s+[XO.]){8})\s+[1-9]\s*$/);if(m)m[2].split(/\s+/).forEach((v,j)=>rows[cols[j]+m[1]]=v);}let boardMatch=Object.keys(rows).length===81&&Object.keys(b).every(p=>b[p]===rows[p]);const m=s.match(/Captured by Black: (\d+); by White: (\d+)/);let capturesMatch=!!m&&cap.X===+m[1]&&cap.O===+m[2];const km=s.match(/Ko point: (none|[A-HJ][1-9])/), koMatch=!!km&&(km[1]==="none"?null:km[1])===ko; checks.push({call:i,throughMove:history.length,boardMatch,capturesMatch,koMatch});if(!boardMatch||!capturesMatch||!koMatch)throw Error("replay mismatch "+i);}
 return {moves:history,checks,captures,allMatched:checks.every(c=>c.boardMatch&&c.capturesMatch&&c.koMatch),finalStones:{Black:Object.values(b).filter(v=>v==="X").length,White:Object.values(b).filter(v=>v==="O").length},physicalCaptures:cap};
}
module.exports = verify;

